-- ScaleFlow initial schema.
-- Conventions:
--   * Entity ids are UUIDv7 generated by the application (time-ordered, see docs/architecture.md §9).
--   * Log-like tables use bigint identity keys.
--   * Status columns are text + CHECK (easier to evolve than enum types).
--   * Every index names the query it serves.

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------
CREATE TABLE users (
  id             uuid PRIMARY KEY,
  email          text NOT NULL CHECK (char_length(email) BETWEEN 3 AND 320),
  name           text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
  password_hash  text NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
-- Login lookup; case-insensitive uniqueness.
CREATE UNIQUE INDEX users_email_lower_key ON users (lower(email));

CREATE TABLE sessions (
  id            uuid PRIMARY KEY,
  user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash    bytea NOT NULL UNIQUE,            -- SHA-256 of the opaque cookie token; lookup on every request
  created_at    timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz NOT NULL,
  revoked_at    timestamptz,
  user_agent    text,
  ip            inet
);
-- Retention: delete expired sessions.
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);
-- FK cascade from users.
CREATE INDEX sessions_user_id_idx ON sessions (user_id);

-- ---------------------------------------------------------------------------
-- Tenancy
-- ---------------------------------------------------------------------------
CREATE TABLE projects (
  id          uuid PRIMARY KEY,
  name        text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
  created_by  uuid NOT NULL REFERENCES users (id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE project_members (
  project_id  uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role        text NOT NULL CHECK (role IN ('owner', 'developer', 'viewer')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, user_id)               -- authorization check: (project, user) -> role
);
-- "Projects I belong to".
CREATE INDEX project_members_user_id_idx ON project_members (user_id);

CREATE TABLE api_keys (
  id            uuid PRIMARY KEY,
  project_id    uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  name          text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
  key_prefix    text NOT NULL,                    -- first characters of the key, for display only
  key_hash      bytea NOT NULL UNIQUE,            -- SHA-256 of the full key; lookup on every API-key request
  scopes        text[] NOT NULL CHECK (scopes <@ ARRAY['jobs:read', 'jobs:write']::text[] AND cardinality(scopes) > 0),
  created_by    uuid REFERENCES users (id) ON DELETE SET NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz,
  revoked_at    timestamptz,
  last_used_at  timestamptz,
  rotated_from  uuid REFERENCES api_keys (id) ON DELETE SET NULL
);
-- Key management page: keys of a project.
CREATE INDEX api_keys_project_id_idx ON api_keys (project_id, created_at DESC);

-- ---------------------------------------------------------------------------
-- Scheduling and jobs (write model)
-- ---------------------------------------------------------------------------
CREATE TABLE scheduled_jobs (
  id              uuid PRIMARY KEY,
  project_id      uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  name            text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
  cron            text NOT NULL,
  timezone        text NOT NULL DEFAULT 'UTC',
  job_type        text NOT NULL,
  queue           text NOT NULL,
  payload         jsonb NOT NULL,
  job_options     jsonb NOT NULL DEFAULT '{}'::jsonb,   -- maxAttempts, backoff, timeoutMs
  enabled         boolean NOT NULL DEFAULT true,
  next_run_at     timestamptz NOT NULL,
  last_run_at     timestamptz,
  last_job_id     uuid,
  version         integer NOT NULL DEFAULT 1,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (project_id, name)
);
-- Cron loop: due schedules.
CREATE INDEX scheduled_jobs_due_idx ON scheduled_jobs (next_run_at) WHERE enabled;

CREATE TABLE jobs (
  id                   uuid PRIMARY KEY,
  project_id           uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  type                 text NOT NULL CHECK (char_length(type) BETWEEN 1 AND 100),
  queue                text NOT NULL CHECK (char_length(queue) BETWEEN 1 AND 50),
  status               text NOT NULL CHECK (status IN
                         ('scheduled', 'queued', 'running', 'retry_wait', 'succeeded', 'failed', 'cancelled')),
  payload              jsonb NOT NULL,
  result               jsonb,
  last_error           jsonb,                     -- {code, message, retryable}; never contains stack traces
  idempotency_key      text CHECK (char_length(idempotency_key) BETWEEN 1 AND 200),
  request_fingerprint  text,                      -- SHA-256 of the canonical request, to detect key reuse with a different body
  correlation_id       text,                      -- request id that created the job, propagated to worker logs
  max_attempts         integer NOT NULL CHECK (max_attempts BETWEEN 1 AND 25),
  attempt_count        integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),   -- attempts ever started (monotonic)
  run_attempts         integer NOT NULL DEFAULT 0 CHECK (run_attempts >= 0),    -- attempts since creation or last manual retry
  backoff              jsonb NOT NULL,            -- {type, baseDelayMs, maxDelayMs}
  timeout_ms           integer NOT NULL CHECK (timeout_ms BETWEEN 100 AND 3600000),
  run_at               timestamptz NOT NULL,      -- earliest execution time (scheduled / retry_wait)
  scheduled_job_id     uuid REFERENCES scheduled_jobs (id) ON DELETE SET NULL,
  locked_by            text,                      -- worker id holding the current attempt
  lease_expires_at     timestamptz,               -- running jobs: recovered by the reaper after this
  version              integer NOT NULL DEFAULT 1,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  queued_at            timestamptz,
  started_at           timestamptz,
  finished_at          timestamptz,
  CONSTRAINT jobs_running_has_lease CHECK (status <> 'running' OR (locked_by IS NOT NULL AND lease_expires_at IS NOT NULL)),
  CONSTRAINT jobs_terminal_has_finished_at CHECK (status NOT IN ('succeeded', 'failed', 'cancelled') OR finished_at IS NOT NULL),
  CONSTRAINT jobs_run_attempts_le_max CHECK (run_attempts <= max_attempts)
);
-- Idempotent submission (NULL keys are not constrained).
CREATE UNIQUE INDEX jobs_project_idempotency_key ON jobs (project_id, idempotency_key);
-- Job list, newest first, keyset pagination on id.
CREATE INDEX jobs_project_id_idx ON jobs (project_id, id DESC);
-- Job list filtered by status (dead-letter view = status 'failed').
CREATE INDEX jobs_project_status_id_idx ON jobs (project_id, status, id DESC);
-- Promoter: due delayed jobs and retries.
CREATE INDEX jobs_due_idx ON jobs (run_at) WHERE status IN ('scheduled', 'retry_wait');
-- Lease reaper: running jobs whose worker vanished.
CREATE INDEX jobs_lease_idx ON jobs (lease_expires_at) WHERE status = 'running';
-- Dispatch reconciler and oldest-queued-age metric.
CREATE INDEX jobs_queued_idx ON jobs (queued_at) WHERE status = 'queued';
-- FK support for ON DELETE SET NULL from scheduled_jobs, and "runs of this schedule".
CREATE INDEX jobs_scheduled_job_id_idx ON jobs (scheduled_job_id, id DESC) WHERE scheduled_job_id IS NOT NULL;
-- Retention: terminal jobs older than N days.
CREATE INDEX jobs_finished_at_idx ON jobs (finished_at) WHERE status IN ('succeeded', 'failed', 'cancelled');

CREATE TABLE job_attempts (
  id              uuid PRIMARY KEY,
  job_id          uuid NOT NULL REFERENCES jobs (id) ON DELETE CASCADE,
  project_id      uuid NOT NULL,                  -- denormalised for tenant-scoped queries
  attempt_number  integer NOT NULL CHECK (attempt_number >= 1),
  worker_id       text NOT NULL,
  status          text NOT NULL CHECK (status IN ('running', 'succeeded', 'failed', 'timed_out', 'lost')),
  started_at      timestamptz NOT NULL,
  finished_at     timestamptz,
  duration_ms     integer,
  queue_wait_ms   integer,
  error           jsonb,
  UNIQUE (job_id, attempt_number)                 -- attempt history of a job, in order
);

CREATE TABLE workers (
  id                 text PRIMARY KEY,            -- <hostname>-<pid>-<random>
  hostname           text NOT NULL,
  pid                integer NOT NULL,
  queues             text[] NOT NULL,
  concurrency        integer NOT NULL CHECK (concurrency > 0),
  status             text NOT NULL CHECK (status IN ('online', 'draining', 'offline')),
  active_jobs        integer NOT NULL DEFAULT 0,
  processed_total    bigint NOT NULL DEFAULT 0,
  failed_total       bigint NOT NULL DEFAULT 0,
  version            text NOT NULL,
  started_at         timestamptz NOT NULL DEFAULT now(),
  last_heartbeat_at  timestamptz NOT NULL DEFAULT now(),
  stopped_at         timestamptz
);
-- Liveness sweep and "online workers" list.
CREATE INDEX workers_status_heartbeat_idx ON workers (status, last_heartbeat_at);

-- ---------------------------------------------------------------------------
-- Logs: outbox, events, audit
-- ---------------------------------------------------------------------------
CREATE TABLE outbox (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  topic         text NOT NULL CHECK (topic IN ('job.dispatch')),
  aggregate_id  uuid NOT NULL,                    -- job id
  payload       jsonb NOT NULL,
  available_at  timestamptz NOT NULL DEFAULT now(),
  attempts      integer NOT NULL DEFAULT 0,
  locked_until  timestamptz,
  last_error    text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  published_at  timestamptz
);
-- Relay claim; published rows drop out of this partial index so it stays small.
CREATE INDEX outbox_pending_idx ON outbox (available_at, id) WHERE published_at IS NULL;
-- Retention of published rows.
CREATE INDEX outbox_published_at_idx ON outbox (published_at) WHERE published_at IS NOT NULL;

CREATE TABLE job_events (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tx_id       xid8 NOT NULL DEFAULT pg_current_xact_id(),   -- commit-ordered cursor, see docs/architecture.md §6
  project_id  uuid NOT NULL,
  job_id      uuid NOT NULL REFERENCES jobs (id) ON DELETE CASCADE,
  type        text NOT NULL,
  data        jsonb NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);
-- Global tailers (SSE hub, projector).
CREATE INDEX job_events_tx_idx ON job_events (tx_id, id);
-- SSE replay per project and project event history.
CREATE INDEX job_events_project_tx_idx ON job_events (project_id, tx_id, id);
-- Job timeline.
CREATE INDEX job_events_job_idx ON job_events (job_id, id);
-- Retention.
CREATE INDEX job_events_created_at_idx ON job_events (created_at);

CREATE TABLE audit_log (
  id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  project_id   uuid REFERENCES projects (id) ON DELETE CASCADE,
  actor_type   text NOT NULL CHECK (actor_type IN ('user', 'api_key', 'system')),
  actor_id     text NOT NULL,
  action       text NOT NULL,
  target_type  text NOT NULL,
  target_id    text NOT NULL,
  metadata     jsonb NOT NULL DEFAULT '{}'::jsonb,
  ip           inet,
  created_at   timestamptz NOT NULL DEFAULT now()
);
-- Audit page per project, newest first.
CREATE INDEX audit_log_project_idx ON audit_log (project_id, id DESC);
-- Retention.
CREATE INDEX audit_log_created_at_idx ON audit_log (created_at);

-- ---------------------------------------------------------------------------
-- Read model (projections of job_events; written only by the projector)
-- ---------------------------------------------------------------------------
CREATE TABLE project_job_counts (
  project_id  uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  status      text NOT NULL,
  count       bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (project_id, status)
);

-- Latency histograms use fixed bucket upper bounds (ms), shared with the application:
-- [5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000, 10000, 30000, 60000, +Inf]
CREATE TABLE job_stats_minutely (
  project_id      uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  bucket          timestamptz NOT NULL,           -- date_trunc('minute', event time)
  submitted       integer NOT NULL DEFAULT 0,
  started         integer NOT NULL DEFAULT 0,
  succeeded       integer NOT NULL DEFAULT 0,
  failed          integer NOT NULL DEFAULT 0,
  retried         integer NOT NULL DEFAULT 0,
  cancelled       integer NOT NULL DEFAULT 0,
  exec_ms_hist    integer[] NOT NULL DEFAULT array_fill(0, ARRAY[14]),
  wait_ms_hist    integer[] NOT NULL DEFAULT array_fill(0, ARRAY[14]),
  exec_ms_sum     bigint NOT NULL DEFAULT 0,
  wait_ms_sum     bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (project_id, bucket)                -- metrics window query: project + time range
);
-- Retention.
CREATE INDEX job_stats_minutely_bucket_idx ON job_stats_minutely (bucket);

CREATE TABLE projection_checkpoints (
  name        text PRIMARY KEY,
  tx_id       xid8 NOT NULL,
  event_id    bigint NOT NULL,
  updated_at  timestamptz NOT NULL DEFAULT now()
);
